pub fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let n = a.len();
    // Pre-allocate capacity to avoid repeated reallocations
    let mut result = Vec::with_capacity(n);

    // Loop counter `i` goes from 0 up to `n`.
    // At each iteration, `result.len() == i` and all elements in `result` so far are 1.
    let mut i = 0;
    while i < n {
        result.push(1);
        i += 1;
    }

    result
}

